data.pageSchema:
{
  "renderer": "page",
  "initData": {},
  "body": [
    {
      "renderer": "form",
      "name": "projectselector",
      "target": "Pagetable",
      "inline": true,
      "controls": [
        {
          "renderer": "select",
          "name": "searchProjectId",
          "clearable": true,
          "placeholder": "请选择项目组",
          "initApi": {
            "method": "get",
            "url": "/api/projects/combo"
          },
          "optionConfig": {
            "text": "text",
            "value": "value"
          }
        },
        {
          "renderer": "action",
          "name": "submit",
          "actionType": "submit",
          "text": "按项目搜索",
          "body": {}
        }
      ]
    },
    {
      "renderer": "table",
      "name": "Pagetable",
      "maxHeight": 600,
      "initApi": {
        "url": "/api/pages?id=${searchProjectId}",
        "method": "get",
        "params": {}
      },
      "columns": [
        {
          "name": "pageName",
          "label": " 页面路径",
          "fixed": false,
          "body": [],
          "width": "200"
        },
        {
          "name": "pageTitle",
          "label": "页面标题",
          "fixed": false,
          "body": []
        },
        {
          "name": "pageIcon",
          "label": "图标",
          "body": [
            {
              "renderer": "html",
              "html": "<i class='<%= data.pageIcon %>' />"
            }
          ]
        },
        {
          "name": "status",
          "label": "状态",
          "fixed": false,
          "body": [
            {
              "renderer": "mapping",
              "name": "status",
              "status": "status",
              "inline": true
            },
            {
              "renderer": "html",
              "html": "<%=data.status? '已上线': '已下线'%>",
              "inline": true
            }
          ]
        },
        {
          "name": "version",
          "label": "版本",
          "fixed": false,
          "body": []
        },
        {
          "name": "updatedBy",
          "label": "更新人",
          "fixed": false,
          "body": []
        },
        {
          "name": "updatedCause",
          "label": "更新原因",
          "fixed": false,
          "body": []
        },
        {
          "name": "groupBy",
          "label": "分组",
          "fixed": false,
          "body": []
        },
        {
          "name": "assets",
          "label": "资源树",
          "fixed": false,
          "body": [
            {
              "renderer": "action",
              "text": " ",
              "plain": true,
              "size": "small",
              "icon": "Flag",
              "actionType": "dialog",
              "actionApi": {
                "url": "",
                "method": "put",
                "params": {}
              },
              "body": {
                "body": [
                  {
                    "renderer": "form",
                    "controls": [
                      {
                        "renderer": "tree",
                        "name": "assets",
                        "label": "依赖库",
                        "tip": "请选择一个版本",
                        "initApi": {
                          "url": "/api/mock/libs",
                          "method": "get",
                          "params": {}
                        },
                        "body": [
                          {
                            "renderer": "html",
                            "html": "<%=data.label%>"
                          }
                        ]
                      }
                    ],
                    "actionApi": {
                      "url": "/api/page?pageId=${pageId}",
                      "method": "put",
                      "params": {
                        "*": "*"
                      }
                    },
                    "name": "UpdateForm",
                    "reload": "IWebsiteContainer"
                  }
                ],
                "footer": [
                  {
                    "renderer": "action",
                    "text": "确定",
                    "actionType": "submit",
                    "actionApi": {
                      "url": "",
                      "method": "post",
                      "params": {}
                    },
                    "params": {},
                    "body": {},
                    "triggered": "UpdateForm"
                  }
                ],
                "closeOnClickModal": true,
                "title": "请选择资源版本",
                "closeOnPressEscape": true,
                "renderer": "dialog"
              },
              "isText": true
            }
          ],
          "type": "-",
          "align": "none"
        },
        {
          "name": "assets",
          "label": "可见性",
          "fixed": false,
          "body": [
            {
              "renderer": "action",
              "plain": true,
              "size": "small",
              "icon": "View",
              "trustOn": -2,
              "actionType": "dialog",
              "actionApi": {
                "url": "",
                "method": "put",
                "params": {}
              },
              "body": {
                "body": [
                  {
                    "renderer": "form",
                    "controls": [
                      {
                        "renderer": "select",
                        "name": "visible",
                        "placeholder": "请输入",
                        "multiple": true,
                        "optionConfig": {
                          "text": "name",
                          "value": "id"
                        },
                        "options": [],
                        "rules": [],
                        "initApi": {
                          "url": "/api/roles?type=list",
                          "method": "get",
                          "cached": false,
                          "params": {}
                        },
                        "label": "角色"
                      }
                    ],
                    "actionApi": {
                      "url": "/api/page?pageId=${pageId}",
                      "method": "put",
                      "params": {
                        "*": "*"
                      }
                    },
                    "name": "UpdateForm",
                    "reload": "IWebsiteContainer"
                  }
                ],
                "footer": [
                  {
                    "renderer": "action",
                    "text": "确定",
                    "actionType": "submit",
                    "actionApi": {
                      "url": "",
                      "method": "post",
                      "params": {}
                    },
                    "params": {},
                    "body": {},
                    "triggered": "UpdateForm"
                  }
                ],
                "closeOnClickModal": true,
                "title": "请选择页面可见角色",
                "closeOnPressEscape": true,
                "renderer": "dialog"
              },
              "isText": true,
              "text": " "
            }
          ],
          "type": "-",
          "align": "none"
        },
        {
          "label": "操作",
          "body": [
            {
              "renderer": "action",
              "text": " ",
              "plain": true,
              "size": "small",
              "icon": "Edit",
              "actionType": "dialog",
              "actionApi": {
                "url": "",
                "method": "put",
                "params": {}
              },
              "body": {
                "body": [
                  {
                    "renderer": "form",
                    "controls": [
                      {
                        "renderer": "input",
                        "name": "pageTitle",
                        "label": "页面标题",
                        "placeholder": "例：用户列表",
                        "type": "text",
                        "validType": "normal",
                        "rules": []
                      },
                      {
                        "renderer": "input",
                        "name": "pageName",
                        "label": "页面路径",
                        "placeholder": "例：users或users/:userId",
                        "type": "text",
                        "validType": "normal",
                        "rules": []
                      },
                      {
                        "renderer": "input",
                        "name": "groupBy",
                        "label": "分组",
                        "readonly": false,
                        "placeholder": "例：分组1",
                        "type": "text",
                        "showWordLimit": false,
                        "showPassword": false,
                        "clearable": true,
                        "rules": []
                      },
                      {
                        "renderer": "switch",
                        "name": "hidden",
                        "label": "隐藏",
                        "defaultValue": false
                      }
                    ],
                    "actionApi": {
                      "url": "/api/page?pageId=${pageId}",
                      "method": "put",
                      "params": {
                        "*": "*"
                      }
                    },
                    "name": "UpdateForm",
                    "reload": "IWebsiteContainer"
                  }
                ],
                "footer": [
                  {
                    "renderer": "action",
                    "text": "确定",
                    "actionType": "submit",
                    "actionApi": {
                      "url": "",
                      "method": "post",
                      "params": {}
                    },
                    "params": {},
                    "body": {},
                    "triggered": "UpdateForm"
                  }
                ],
                "title": "",
                "closeOnClickModal": true,
                "renderer": "dialog"
              },
              "isText": true
            },
            {
              "renderer": "action",
              "text": " ",
              "type": "danger",
              "size": "small",
              "popupType": "confirm",
              "actionType": "ajax",
              "actionApi": {
                "url": "/api/page/${id}",
                "method": "delete",
                "params": {}
              },
              "body": {},
              "icon": "Delete",
              "reload": "IWebsiteContainer",
              "confirmTitle": "确定要删除吗？",
              "isText": true
            },
            {
              "renderer": "action",
              "text": " ",
              "type": "danger",
              "size": "small",
              "popupType": "confirm",
              "actionType": "ajax",
              "actionApi": {
                "url": "/api/page/offline",
                "method": "put",
                "params": {
                  "*": "*"
                }
              },
              "body": {},
              "icon": "VideoPause",
              "reload": "IWebsiteContainer",
              "visibleOn": "data.status == 1",
              "confirmTitle": "确定要下线吗？",
              "isText": true
            },
            {
              "renderer": "action",
              "text": " ",
              "type": "danger",
              "size": "small",
              "popupType": "confirm",
              "actionType": "ajax",
              "actionApi": {
                "url": "/api/page/online",
                "method": "put",
                "params": {
                  "*": "*"
                }
              },
              "body": {},
              "icon": "VideoPlay",
              "reload": "IWebsiteContainer",
              "visibleOn": "data.status == 0",
              "confirmTitle": "确定要上线吗？",
              "isText": true
            }
          ],
          "width": "200"
        }
      ],
      "actions": [
        {
          "renderer": "action",
          "actionType": "dialog",
          "type": "success",
          "size": "small",
          "text": "新建空白页",
          "body": {
            "size": "45%",
            "header": {
              "renderer": "html",
              "html": "新建任务"
            },
            "body": {
              "renderer": "form",
              "name": "Pageform",
              "actionApi": {
                "url": "/api/page",
                "params": {
                  "*": "*"
                },
                "method": "post"
              },
              "controls": [
                {
                  "renderer": "select",
                  "name": "projectId",
                  "label": "所属项目",
                  "placeholder": "请选择页面所属项目",
                  "joinValue": false,
                  "initApi": {
                    "url": "/api/projects/combo",
                    "method": "get"
                  },
                  "requiredOn": "true",
                  "optionConfig": {
                    "text": "text",
                    "value": "value"
                  },
                  "options": [
                    {
                      "text": "文案1",
                      "value": "value1"
                    },
                    {
                      "text": "文案2",
                      "value": "value2"
                    }
                  ]
                },
                {
                  "renderer": "input",
                  "name": "pageName",
                  "label": "路径",
                  "rules": [
                    {
                      "exp": "!/^[a-zA-Z]+(\\/\\:\\w+)*$/.test(data.name)",
                      "type": "exp",
                      "trigger": "blur"
                    },
                    {
                      "type": "api",
                      "trigger": "blur",
                      "exp": "/api/page/${projectId}/${pageName}/valid"
                    }
                  ],
                  "requiredOn": "true",
                  "visibleOn": "data.projectId",
                  "placeholder": "例：users或users/:userId",
                  "type": "text",
                  "validType": "normal"
                },
                {
                  "renderer": "input",
                  "name": "pageTitle",
                  "label": "标题",
                  "rules": [
                    {
                      "exp": "!/^([\\u4e00-\\u9fa5]|[a-zA-Z0-9]){1,10}$/.test(data.label)",
                      "message": "不允许输入除字母、数字、中文外的特殊字符",
                      "type": "exp",
                      "trigger": "blur"
                    }
                  ],
                  "requiredOn": "true",
                  "placeholder": "例：用户列表",
                  "type": "text",
                  "validType": "normal"
                },
                {
                  "renderer": "input",
                  "name": "groupBy",
                  "label": "分组",
                  "requiredOn": "false",
                  "placeholder": "例：分组1",
                  "type": "text",
                  "rules": []
                },
                {
                  "renderer": "switch",
                  "name": "hidden",
                  "label": "隐藏",
                  "defaultValue": false
                },
                {
                  "renderer": "input",
                  "name": "icon",
                  "label": "图标",
                  "placeholder": "例：Edit",
                  "type": "text",
                  "rules": []
                }
              ],
              "reload": "IWebsiteContainer"
            },
            "footer": [
              {
                "renderer": "action",
                "actionType": "submit",
                "triggered": "Pageform",
                "closable": true,
                "text": "创建"
              },
              {
                "renderer": "action",
                "actionType": "reset",
                "triggered": "Pageform",
                "text": "重置"
              }
            ],
            "renderer": "dialog"
          },
          "icon": "Plus"
        }
      ],
      "showExport": true,
      "height": 490,
      "showDynamicColumn": true,
      "reactive": true,
      "lazy": true,
      "loadMore": "/api/pages?pageId=${pageId}",
      "updateOnRowId": "id",
      "selectableOn": "pageId",
      "rowKey": "updatedAt"
    }
  ],
  "res": "if(url.includes('/api/pages?id=')) {\n  res.data.rows.forEach(i => {\n    i.hasChildren = true;\n  });\n}"
}
